mod tests {
    use super::*;

    fn row(salience: f64, status: &str, helpful: i64, access: i64, last_access: i64) -> MemoryRow {
        MemoryRow {
            id: 1,
            repo_id: None,
            kind: "lesson".to_string(),
            content: String::new(),
            salience,
            status: status.to_string(),
            last_access,
            access_count: access,
            helpful_count: helpful,
            stale_at: None,
            superseded_by: None,
            helpful_at: None,
        }
    }

    #[test]
    fn stale_memories_are_demoted_not_dropped() {
        let now = 1_000_000;
        let live = recall_score(0.8, &row(0.7, "live", 0, 0, now), now, 29.0);
        let stale = recall_score(0.8, &row(0.7, "stale", 0, 0, now), now, 29.0);
        assert!(stale > 0.0);
        assert!((stale / live - 0.5).abs() < 1e-9);
    }

    #[test]
    fn disuse_decays_and_utility_reinforces() {
        let now = 1_000_000;
        let month = 30 * 86_400;
        let fresh = recall_score(0.8, &row(0.7, "live", 0, 0, now), now, 29.0);
        let old = recall_score(0.8, &row(0.7, "live", 0, 0, now - month), now, 29.0);
        assert!(old < fresh);
        let helpful = recall_score(0.8, &row(0.7, "live", 5, 5, now - month), now, 29.0);
        assert!(helpful > old);
    }

    #[test]
    fn query_score_ignores_recency_and_ranks_by_similarity() {
        let now = 1_000_000;
        let year = 365 * 86_400;
        let fresh = query_score(0.6, &row(0.5, "live", 0, 0, now));
        let old = query_score(0.6, &row(0.5, "live", 0, 0, now - year));
        assert_eq!(fresh, old);
        let salient = query_score(0.50, &row(1.0, "live", 0, 0, now));
        let relevant = query_score(0.65, &row(0.05, "live", 0, 0, now));
        assert!(relevant > salient);
        let stale = query_score(0.6, &row(0.5, "stale", 0, 0, now));
        assert!((stale / fresh - 0.5).abs() < 1e-9);
    }

    #[test]
    fn salience_composition_is_bounded() {
        assert!(compose_salience(0.0, 0.0, 0.0) >= 0.05);
        assert!(compose_salience(1.0, 1.0, 1.0) <= 1.0);
        assert!(compose_salience(0.2, 0.0, 0.9) > compose_salience(0.2, 0.0, 0.2));
    }
}

